     void clear() {
         pending.clear();
     }

     @Override
     public void close() {
         if (!closed.compareAndSet(false, true)) {
             return;
         }
         pending.clear();
         scheduler.shutdownNow();
     }

     private record Key(String sessionId, int target) {
     }

     private static final class Pending {
         private volatile Event event;

         private Pending(Event event) {
             this.event = event;
         }
     }
