   view.setUint16(4, VERSION, true);
   view.setUint16(6, 0x0001, true); // HOST_TO_GUEST
   view.setUint32(12, 1, true);
   view.setUint8(HEADER_SIZE, CAT_META);
   view.setUint8(HEADER_SIZE + 1, CMD_PONG);
   return out;
 }

