    vi.stubGlobal("fetch", async () => ({
      ok: true,
      text: async () => '<svg viewBox="0 0 24 24" fill="currentColor">' + PAUSE + "</svg>",
    }));

    const el = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    el.setAttribute("data-pathland-id", "1");
